INSERT INTO `inventory_log` (`id`, `udi`, `name`, `type`, `change_qty`, `before_qty`, `after_qty`, `ref_no`, `operator`, `date`, `note`) VALUES (113, '', '回归测试CT-973156', '出库扣减', -2, 10, 8, 'CK-20260817-014', '郑磊', '2026-08-17', '销售出库扣减');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (1, 'SOP流程', 'SOP-YS-01', '首营企业与首营品种审核流程', 'GSP第28-32条', '对供应商/生产企业的合法资质和产品注册信息进行首营审核，确保采购来源合法、产品合规。', '<h3>流程说明</h3><p>首营审核是医疗器械经营质量管理的第一道关口，涵盖供应商资质审核和产品资质审核两个维度。</p><h3>关键控制点</h3><ul><li>供应商须持有有效《医疗器械经营/生产许可证》</li><li>产品须持有有效《医疗器械注册证》</li><li>资质文件须在有效期内，过期即停止采购</li><li>质量负责人须签字批准方可建档</li></ul><h3>审核要点</h3><p>核对供应商营业执照与经营/生产许可证的名称、地址、法定代表人、经营范围是否一致；核对产品注册证的有效期、适用范围、规格型号是否与采购产品一致。</p>', '[{"name": "供应商资质收集", "desc": "收集供应商营业执照、经营/生产许可证、GSP/GMP证书等", "legal_basis": "GSP第28条", "responsible": "采购员", "records": "供应商资质档案"}, {"name": "资料初审", "desc": "审核资质完整性、有效性、经营范围覆盖情况", "legal_basis": "GSP第29条", "responsible": "质管员", "records": "首营审核表"}, {"name": "现场考察(必要时)", "desc": "对首次合作或高风险供应商进行现场考察", "legal_basis": "GSP第30条", "responsible": "质量负责人", "records": "现场考察报告"}, {"name": "质量负责人审核", "desc": "质量负责人对首营资料进行最终审核批准", "legal_basis": "GSP第31条", "responsible": "质量负责人", "records": "审核意见"}, {"name": "系统建档", "desc": "审核通过后在系统中建立供应商和产品档案", "legal_basis": "GSP第32条", "responsible": "质管员", "records": "系统建档记录"}, {"name": "动态管理", "desc": "定期跟踪资质有效期，到期前60天预警", "legal_basis": "GSP第28条", "responsible": "质管员", "records": "资质跟踪台账"}]', '发布', '首营,审核,供应商,资质', 0, 1, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '首营管理');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (2, 'SOP流程', 'SOP-YS-02', '首营变更管理流程', 'GSP第32条', '供应商或产品资质信息发生变更时的审核、更新和重新建档流程。', '<h3>流程说明</h3><p>当供应商许可证变更、产品注册证更新、企业名称/地址变更等情况发生时，须按本流程进行变更审核。</p><h3>变更类型</h3><ul><li>供应商资质变更（许可证到期换证、名称变更、地址变更等）</li><li>产品资质变更（注册证到期续展、规格变更、型号变更等）</li><li>供应商质量状况变更（GSP/GMP证书被吊销、行政处罚等）</li></ul>', '[{"name": "变更信息收集", "desc": "收集供应商变更通知和相关证明文件", "legal_basis": "GSP第32条", "responsible": "采购员", "records": "变更通知单"}, {"name": "变更评估", "desc": "评估变更对产品质量和合规性的影响", "legal_basis": "GSP第32条", "responsible": "质管员", "records": "变更评估表"}, {"name": "质量负责人审批", "desc": "质量负责人审批变更事项", "legal_basis": "GSP第32条", "responsible": "质量负责人", "records": "审批意见"}, {"name": "系统更新", "desc": "更新供应商/产品档案信息", "legal_basis": "GSP第32条", "responsible": "质管员", "records": "档案更新记录"}, {"name": "通知相关部门", "desc": "通知采购、仓储、销售等相关部门", "legal_basis": "GSP第32条", "responsible": "质管员", "records": "通知记录"}]', '发布', '首营,变更,供应商', 0, 2, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '首营管理');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (3, 'SOP流程', 'SOP-CG-01', '采购计划编制与审批流程', 'GSP第33-38条', '采购需求收集、采购计划编制、审核审批和供应商选择的全流程管理。', '<h3>流程说明</h3><p>采购计划是采购管理的起点，须根据实际需求和库存情况科学编制，经审核批准后执行。</p><h3>编制要点</h3><ul><li>结合库存预警和销售需求确定采购品种和数量</li><li>选择已审核合格的供应商</li><li>采购计划须经质量负责人审核批准</li><li>紧急采购须单独审批并记录原因</li></ul>', '[{"name": "需求收集", "desc": "收集各部门采购需求，结合库存情况确定采购清单", "legal_basis": "GSP第33-35条", "responsible": "采购员", "records": "采购需求表"}, {"name": "编制采购计划", "desc": "编制采购计划，明确品名、规格、数量、预算、供应商", "legal_basis": "GSP第36条", "responsible": "采购员", "records": "采购计划表"}, {"name": "质量审核", "desc": "质量负责人审核采购计划的合规性", "legal_basis": "GSP第37条", "responsible": "质量负责人", "records": "审核意见"}, {"name": "审批执行", "desc": "负责人审批后下达采购订单", "legal_basis": "GSP第38条", "responsible": "质量负责人", "records": "采购计划审批单"}]', '发布', '采购,计划,审批', 0, 3, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '采购验收');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (4, 'SOP流程', 'SOP-CG-02', '到货验收与入库流程', 'GSP第39-48条', '从到货收货、验收检查到入库登记的全流程，确保入库产品数量准确、质量合格。', '<h3>流程说明</h3><p>到货验收是保证入库产品质量的关键环节，须严格执行收货、验收、入库三步分离制度。</p><h3>验收内容</h3><ul><li>核对实物与合同/发票/随货同行单一致性</li><li>检查外包装完好性、标签标识清晰性</li><li>检查产品批号、生产日期、效期、注册证号</li><li>运输条件检查（冷链产品须查温度记录）</li><li>不合格品须隔离存放并标识</li></ul>', '[{"name": "到货收货", "desc": "核对运输单据，检查外包装完好性，签收货物", "legal_basis": "GSP第39-41条", "responsible": "收货员", "records": "收货记录"}, {"name": "验收检查", "desc": "检查产品外观、数量、批号、效期、注册证号等", "legal_basis": "GSP第42-45条", "responsible": "验收员", "records": "验收记录单"}, {"name": "验收结论", "desc": "填写验收记录，给出验收结论（合格/不合格）", "legal_basis": "GSP第46条", "responsible": "验收员", "records": "验收结论单"}, {"name": "合格品入库", "desc": "验收合格品按分类入库，建立库存台账", "legal_basis": "GSP第47条", "responsible": "库管员", "records": "入库单"}, {"name": "不合格品隔离", "desc": "不合格品移至不合格品区，标识并登记", "legal_basis": "GSP第48条", "responsible": "质管员", "records": "不合格品登记表"}]', '发布', '验收,入库,采购', 0, 4, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '采购验收');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (5, 'SOP流程', 'SOP-CG-03', '产品验收与质量放行流程', 'GSP第54-58条', '产品到货后的质量验收、检验报告核查、质量放行决策和验收记录管理。', '<h3>流程说明</h3><p>产品验收是比到货验收更深入的质量检查环节，须由专职验收员执行并留存记录。</p><h3>验收维度</h3><ul><li>资质文件验收：注册证、检验报告、合格证</li><li>实物质量验收：外观、包装、标签、说明书</li><li>运输条件验收：冷链温度记录、防震防潮措施</li><li>批次管理验收：批号、生产日期、效期记录</li></ul>', '[{"name": "资料核查", "desc": "核查产品注册证、检验报告、合格证等随货文件", "legal_basis": "GSP第54条", "responsible": "验收员", "records": "资料核查记录"}, {"name": "实物验收", "desc": "检查产品外观、包装、标签、说明书等", "legal_basis": "GSP第55条", "responsible": "验收员", "records": "实物验收记录"}, {"name": "运输条件检查", "desc": "检查冷链温度记录、防震防潮措施", "legal_basis": "GSP第56条", "responsible": "验收员", "records": "运输条件检查表"}, {"name": "质量放行决策", "desc": "综合验收结果做出质量放行/拒收决策", "legal_basis": "GSP第57条", "responsible": "质管员", "records": "质量放行单"}, {"name": "验收记录归档", "desc": "验收全过程记录归档保存", "legal_basis": "GSP第58条", "responsible": "验收员", "records": "验收档案"}]', '发布', '产品验收,质量放行,检验', 0, 5, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '采购验收');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (6, 'SOP流程', 'SOP-CC-01', '仓储分区与温湿度管理流程', 'GSP第46-55条', '仓储分区管理、温湿度监控、超限报警和记录管理的标准化流程。', '<h3>流程说明</h3><p>仓储分区和温湿度管理是保障医疗器械在库质量的基础。</p><h3>温湿度要求</h3><table border="1" style="border-collapse:collapse"><tr><th style="padding:6px">库区</th><th style="padding:6px">温度</th><th style="padding:6px">湿度</th></tr><tr><td style="padding:6px">常温库</td><td style="padding:6px">0-30℃</td><td style="padding:6px">35%-75%</td></tr><tr><td style="padding:6px">阴凉库</td><td style="padding:6px">≤20℃</td><td style="padding:6px">35%-75%</td></tr><tr><td style="padding:6px">冷藏库</td><td style="padding:6px">2-8℃</td><td style="padding:6px">—</td></tr></table><h3>监控频次</h3><ul><li>每日至少2次人工记录（上午/下午各1次）</li><li>温湿度监测系统24小时自动监测</li><li>超限自动报警并立即处理</li></ul>', '[{"name": "分区分类存放", "desc": "按医疗器械类别、温湿度要求分区分类存放", "legal_basis": "GSP第46-48条", "responsible": "库管员", "records": "库区分布图"}, {"name": "色标管理", "desc": "合格品绿色、不合格品红色、待验黄色标识", "legal_basis": "GSP第49条", "responsible": "库管员", "records": "色标管理记录"}, {"name": "温湿度记录", "desc": "每日2次记录温湿度，系统24小时自动监测", "legal_basis": "GSP第54-55条", "responsible": "库管员", "records": "温湿度记录表"}, {"name": "超限报警处理", "desc": "温湿度超限时立即报警并采取调节措施", "legal_basis": "GSP第55条", "responsible": "库管员", "records": "异常处理记录"}, {"name": "设备维护", "desc": "定期维护温湿度监测设备、空调、除湿机等", "legal_basis": "GSP第53条", "responsible": "设备管理员", "records": "设备维护记录"}]', '发布', '仓储,温湿度,分区', 0, 6, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '仓储养护');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (7, 'SOP流程', 'SOP-CC-02', '在库养护与效期管理流程', 'GSP第56-58条, 第68-72条', '定期养护检查、效期预警管理、近效期产品标识和盘点管理的全流程。', '<h3>流程说明</h3><p>在库养护是保障医疗器械在库期间质量稳定的重要措施。</p><h3>养护频次</h3><ul><li>日常养护：每月1次，检查外观、包装、标签</li><li>重点养护：每季度1次，针对高值/高风险/特殊储存产品</li><li>全面养护：每年1次，覆盖全部在库产品</li></ul><h3>效期管理</h3><ul><li>近效期6个月：黄色预警标识</li><li>近效期3个月：红色预警标识，优先出库</li><li>过期产品：立即移至不合格品区</li></ul>', '[{"name": "制定养护计划", "desc": "按月/季/年制定养护计划", "legal_basis": "GSP第56条", "responsible": "养护员", "records": "养护计划表"}, {"name": "养护检查", "desc": "按计划检查产品外观、包装、标签、储存条件", "legal_basis": "GSP第56条", "responsible": "养护员", "records": "养护记录"}, {"name": "效期预警", "desc": "检查在库产品效期，更新预警标识", "legal_basis": "GSP第68-72条", "responsible": "库管员", "records": "效期预警表"}, {"name": "近效期处理", "desc": "近效期产品优先出库或退换货", "legal_basis": "GSP第70条", "responsible": "库管员", "records": "近效期处理记录"}, {"name": "定期盘点", "desc": "每季度盘点1次，确保账物相符", "legal_basis": "GSP第58条", "responsible": "库管员", "records": "盘点报告"}]', '发布', '养护,效期,盘点', 0, 7, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '仓储养护');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (8, 'SOP流程', 'SOP-CC-03', '不合格品隔离与处置流程', 'GSP第57条', '不合格品的发现、标识、隔离、调查、处置和记录的全流程管理。', '<h3>流程说明</h3><p>不合格品管理是防止不合格品流入市场的关键控制点，须严格执行隔离、标识和处置程序。</p><h3>不合格品来源</h3><ul><li>到货验收不合格</li><li>在库养护发现质量问题</li><li>客户退货/投诉发现质量问题</li><li>监管部门抽检不合格</li><li>召回产品</li></ul>', '[{"name": "不合格品标识", "desc": "发现不合格品后立即贴红色不合格标识", "legal_basis": "GSP第57条", "responsible": "发现人", "records": "不合格标识"}, {"name": "移至不合格品区", "desc": "将不合格品移至专设的不合格品区隔离存放", "legal_basis": "GSP第57条", "responsible": "库管员", "records": "移库记录"}, {"name": "不合格品登记", "desc": "登记不合格品信息，包括品名、批号、数量、不合格原因", "legal_basis": "GSP第57条", "responsible": "质管员", "records": "不合格品登记表"}, {"name": "调查分析", "desc": "调查不合格原因，确定处置方案", "legal_basis": "GSP第57条", "responsible": "质管员", "records": "调查报告"}, {"name": "处置执行", "desc": "按审批方案执行退货/销毁/换货", "legal_basis": "GSP第57条", "responsible": "库管员", "records": "处置记录"}, {"name": "记录归档", "desc": "处置全过程记录归档保存", "legal_basis": "GSP第57条", "responsible": "质管员", "records": "处置档案"}]', '发布', '不合格品,隔离,处置', 0, 8, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '仓储养护');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (9, 'SOP流程', 'SOP-XS-01', '客户资质审核与销售管理流程', 'GSP第59-60条', '客户首营资质审核、销售订单管理和客户档案维护的全流程。', '<h3>流程说明</h3><p>销售出库前必须完成客户资质审核，确保客户持有合法有效经营/使用许可证。</p><h3>客户资质要求</h3><ul><li>医疗机构：《医疗机构执业许可证》</li><li>经营企业：《医疗器械经营许可证》或备案凭证</li><li>营业执照：在有效期内，经营范围覆盖</li></ul>', '[{"name": "客户资质收集", "desc": "收集客户营业执照、经营/使用许可证等资质", "legal_basis": "GSP第59条", "responsible": "销售助理", "records": "客户资质档案"}, {"name": "资质审核", "desc": "审核客户资质的完整性、有效性、经营范围", "legal_basis": "GSP第59条", "responsible": "质管员", "records": "客户审核表"}, {"name": "客户建档", "desc": "审核通过后建立客户档案", "legal_basis": "GSP第59条", "responsible": "销售助理", "records": "客户档案"}, {"name": "销售开单", "desc": "根据客户需求创建销售出库单", "legal_basis": "GSP第60条", "responsible": "销售助理", "records": "销售出库单"}, {"name": "动态跟踪", "desc": "定期跟踪客户资质有效期，到期前60天预警", "legal_basis": "GSP第59条", "responsible": "质管员", "records": "资质跟踪台账"}]', '发布', '客户,资质,销售', 1, 9, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '销售出库');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (10, 'SOP流程', 'SOP-XS-02', '出库复核与运输配送流程', 'GSP第61-67条', '出库双人复核、质量放行、运输配送和客户签收的全流程管理。', '<h3>流程说明</h3><p>出库复核是产品离开企业的最后一道质量关口，必须严格执行双人复核制度。</p><h3>复核要点</h3><ul><li>核对出库产品品名、规格、批号、数量、效期</li><li>检查产品外观和包装完好性</li><li>质量放行人签字确认</li><li>运输条件须符合产品要求（特别是冷链产品）</li></ul>', '[{"name": "出库拣货", "desc": "根据出库单从库区拣选产品", "legal_basis": "GSP第61条", "responsible": "库管员", "records": "拣货单"}, {"name": "双人复核", "desc": "制单人与复核人双重核对出库产品信息", "legal_basis": "GSP第62-63条", "responsible": "复核员", "records": "出库复核记录"}, {"name": "质量放行", "desc": "质量放行人对出库产品进行质量确认", "legal_basis": "GSP第64条", "responsible": "质管员", "records": "质量放行记录"}, {"name": "运输配送", "desc": "按产品温湿度要求安排运输工具和方式", "legal_basis": "GSP第65-66条", "responsible": "物流员", "records": "运输交接单"}, {"name": "客户签收", "desc": "客户签收并确认到货品质和数量", "legal_basis": "GSP第67条", "responsible": "销售助理", "records": "签收回执"}]', '发布', '出库,复核,运输', 0, 10, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '销售出库');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (11, 'SOP流程', 'SOP-ZL-01', '不良事件监测与报告流程', '不良事件监测办法', '医疗器械不良事件的发现、评估、时限内上报、调查分析和纠正预防的全流程。', '<h3>流程说明</h3><p>医疗器械不良事件监测是法定义务，须建立主动监测和被动收集双重机制。</p><h3>上报时限</h3><table border="1" style="border-collapse:collapse"><tr><th style="padding:6px">严重程度</th><th style="padding:6px">上报时限</th><th style="padding:6px">上报渠道</th></tr><tr><td style="padding:6px">导致死亡</td><td style="padding:6px">5个工作日内</td><td style="padding:6px">国家不良事件监测系统</td></tr><tr><td style="padding:6px">导致严重伤害</td><td style="padding:6px">15个工作日内</td><td style="padding:6px">国家不良事件监测系统</td></tr><tr><td style="padding:6px">一般不良事件</td><td style="padding:6px">30个工作日内</td><td style="padding:6px">国家不良事件监测系统</td></tr></table>', '[{"name": "事件发现", "desc": "发现或获知医疗器械不良事件", "legal_basis": "不良事件办法第7条", "responsible": "发现人", "records": "不良事件登记表"}, {"name": "初步评估", "desc": "评估事件严重程度和上报时限", "legal_basis": "不良事件办法第8条", "responsible": "质管员", "records": "评估记录"}, {"name": "时限内上报", "desc": "按严重程度在规定时限内上报国家不良事件监测系统", "legal_basis": "不良事件办法第10条", "responsible": "质管员", "records": "上报回执"}, {"name": "调查分析", "desc": "调查事件原因，分析是否与产品质量相关", "legal_basis": "不良事件办法第12条", "responsible": "质量负责人", "records": "调查报告"}, {"name": "纠正预防", "desc": "制定并实施纠正和预防措施", "legal_basis": "不良事件办法第15条", "responsible": "质管员", "records": "CAPA记录"}, {"name": "跟踪关闭", "desc": "跟踪措施有效性，确认事件关闭", "legal_basis": "不良事件办法第17条", "responsible": "质量负责人", "records": "关闭报告"}]', '发布', '不良事件,监测,上报', 0, 11, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '质量监控');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (12, 'SOP流程', 'SOP-ZL-02', '产品召回管理流程', '医疗器械召回管理办法', '召回决策、计划制定、通知客户、产品回收、效果评估和总结报告的全流程。', '<h3>流程说明</h3><p>医疗器械召回是控制已上市医疗器械风险的重要措施。</p><h3>召回级别</h3><table border="1" style="border-collapse:collapse"><tr><th style="padding:6px">级别</th><th style="padding:6px">通知时限</th><th style="padding:6px">适用情形</th></tr><tr><td style="padding:6px">一级召回</td><td style="padding:6px">24小时内</td><td style="padding:6px">使用可能引起严重健康损害或死亡</td></tr><tr><td style="padding:6px">二级召回</td><td style="padding:6px">48小时内</td><td style="padding:6px">使用可能引起暂时性或可逆健康损害</td></tr><tr><td style="padding:6px">三级召回</td><td style="padding:6px">72小时内</td><td style="padding:6px">使用引起健康损害的可能性较小</td></tr></table>', '[{"name": "召回决策", "desc": "根据风险信息评估是否需要召回及召回级别", "legal_basis": "召回办法第14条", "responsible": "质量负责人", "records": "召回评估报告"}, {"name": "制定召回计划", "desc": "制定召回计划，明确范围、时限、方式", "legal_basis": "召回办法第15条", "responsible": "质管员", "records": "召回计划书"}, {"name": "通知客户/公告", "desc": "按级别时限通知所有受影响客户", "legal_basis": "召回办法第16-18条", "responsible": "销售助理", "records": "通知记录"}, {"name": "产品回收", "desc": "回收受影响产品，记录回收数量", "legal_basis": "召回办法第20条", "responsible": "库管员", "records": "回收记录"}, {"name": "效果评估", "desc": "评估召回效果，计算召回率", "legal_basis": "召回办法第22条", "responsible": "质量负责人", "records": "效果评估报告"}, {"name": "总结报告", "desc": "编制召回总结报告并上报监管部门", "legal_basis": "召回办法第24条", "responsible": "质量负责人", "records": "召回总结报告"}]', '发布', '召回,追溯,处置', 0, 12, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '质量监控');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (13, 'SOP流程', 'SOP-ZL-03', '追溯体系管理流程', 'GSP第46条, 第67条', '产品批号管理、进销存追溯、流向追踪和追溯记录维护的全流程。', '<h3>流程说明</h3><p>追溯体系是医疗器械全生命周期管理的基础，须确保从采购到销售全过程可追溯。</p><h3>追溯要素</h3><ul><li>采购追溯：供应商、采购合同、到货验收记录</li><li>仓储追溯：入库批次、储存位置、养护记录</li><li>销售追溯：客户信息、出库记录、运输记录</li><li>产品信息：品名、规格、批号、生产日期、效期</li></ul>', '[{"name": "批号建档", "desc": "产品入库时建立批号档案，记录完整信息", "legal_basis": "GSP第46条", "responsible": "库管员", "records": "批号档案"}, {"name": "进销存记录", "desc": "记录每批产品的采购、入库、出库信息", "legal_basis": "GSP第46条", "responsible": "库管员", "records": "进销存台账"}, {"name": "流向追踪", "desc": "追踪每批产品的销售流向和客户信息", "legal_basis": "GSP第67条", "responsible": "销售助理", "records": "产品流向表"}, {"name": "追溯查询", "desc": "根据批号可正向追踪到客户，反向追溯到供应商", "legal_basis": "GSP第67条", "responsible": "质管员", "records": "追溯查询记录"}, {"name": "记录保存", "desc": "追溯记录保存不少于产品效期后2年", "legal_basis": "GSP第67条", "responsible": "质管员", "records": "归档记录"}]', '发布', '追溯,批号,流向', 0, 13, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '质量监控');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (14, 'SOP流程', 'SOP-ZH-01', '人员培训与健康管理流程', 'GSP第18-20条', '培训需求分析、年度培训计划、培训实施考核、健康体检和健康档案管理的全流程。', '<h3>流程说明</h3><p>人员培训和健康管理是GSP的基本要求，所有接触医疗器械的人员须经过培训并持有效健康证上岗。</p><h3>健康体检要求</h3><ul><li>新员工入职前体检</li><li>在岗员工每年体检1次</li><li>体检项目包括：传染病、皮肤病、精神疾病等</li><li>健康证有效期1年</li></ul>', '[{"name": "培训需求分析", "desc": "分析岗位培训需求，确定培训内容", "legal_basis": "GSP第18条", "responsible": "质量负责人", "records": "培训需求表"}, {"name": "年度培训计划", "desc": "制定年度培训计划并审批", "legal_basis": "GSP第18条", "responsible": "质管员", "records": "年度培训计划"}, {"name": "培训实施考核", "desc": "按计划实施培训并进行考核", "legal_basis": "GSP第19条", "responsible": "质管员", "records": "培训记录+考核成绩"}, {"name": "培训档案", "desc": "建立员工培训档案，保存培训记录", "legal_basis": "GSP第19条", "responsible": "行政办公员", "records": "培训档案"}, {"name": "健康体检", "desc": "组织员工进行年度健康体检", "legal_basis": "GSP第20条", "responsible": "行政办公员", "records": "体检报告"}, {"name": "健康档案", "desc": "建立员工健康档案，跟踪健康证有效期", "legal_basis": "GSP第20条", "responsible": "行政办公员", "records": "健康档案"}]', '发布', '培训,健康,人员', 0, 14, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '综合管理');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (15, 'SOP流程', 'SOP-ZH-02', '设施设备校准与验证流程', 'GSP第21-27条, 使用办法第21条', '校准计划编制、送检/现场校准、结果确认、标识张贴、校准记录和周期管理。', '<h3>流程说明</h3><p>计量器具和关键设备的校准是保证测量准确性的基础，须按周期进行校准并留存记录。</p><h3>校准周期参考</h3><table border="1" style="border-collapse:collapse"><tr><th style="padding:6px">设备</th><th style="padding:6px">校准周期</th></tr><tr><td style="padding:6px">温湿度计</td><td style="padding:6px">每年1次</td></tr><tr><td style="padding:6px">电子秤</td><td style="padding:6px">每半年1次</td></tr><tr><td style="padding:6px">万用表</td><td style="padding:6px">每年1次</td></tr><tr><td style="padding:6px">温湿度监测系统</td><td style="padding:6px">每年1次</td></tr></table>', '[{"name": "校准计划", "desc": "编制年度校准计划，明确校准对象、周期、机构", "legal_basis": "使用办法第21条", "responsible": "计量员", "records": "校准计划表"}, {"name": "送检/现场校准", "desc": "送检或邀请校准机构现场校准", "legal_basis": "使用办法第21条", "responsible": "计量员", "records": "校准委托单"}, {"name": "结果确认", "desc": "确认校准结果是否符合要求", "legal_basis": "使用办法第21条", "responsible": "计量员", "records": "校准证书"}, {"name": "标识张贴", "desc": "在校准合格的设备上张贴校准合格标识", "legal_basis": "使用办法第21条", "responsible": "计量员", "records": "标识记录"}, {"name": "校准记录", "desc": "填写校准记录，归档保存校准证书", "legal_basis": "使用办法第21条", "responsible": "计量员", "records": "校准档案"}, {"name": "周期管理", "desc": "跟踪校准有效期，到期前30天预警", "legal_basis": "使用办法第21条", "responsible": "计量员", "records": "校准台账"}]', '发布', '校准,验证,计量', 0, 15, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '综合管理');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (16, 'SOP流程', 'SOP-ZH-03', '质量管理体系内审流程', 'GSP第7-13条', '内审计划编制、首次会议、现场审核、不符合项报告、纠正措施和末次会议总结。', '<h3>流程说明</h3><p>内部审核是质量管理体系自我完善的重要机制，每年至少进行1次全面内审。</p><h3>内审要点</h3><ul><li>审核范围覆盖GSP全部条款</li><li>审核人员须经过培训且独立于被审核部门</li><li>不符合项须制定纠正措施并跟踪验证</li><li>内审报告须经质量负责人审批</li></ul>', '[{"name": "内审计划", "desc": "编制年度内审计划，明确范围、频次、人员", "legal_basis": "GSP第7条", "responsible": "质量负责人", "records": "内审计划"}, {"name": "首次会议", "desc": "召开首次会议，宣布审核目的和安排", "legal_basis": "GSP第8条", "responsible": "质量负责人", "records": "首次会议记录"}, {"name": "现场审核", "desc": "按检查表逐项审核，收集证据", "legal_basis": "GSP第9-11条", "responsible": "内审员", "records": "审核检查表"}, {"name": "不符合项报告", "desc": "对发现的不符合项开具报告", "legal_basis": "GSP第12条", "responsible": "内审员", "records": "不符合项报告"}, {"name": "纠正措施", "desc": "责任部门制定并实施纠正措施", "legal_basis": "GSP第12条", "responsible": "责任部门", "records": "纠正措施记录"}, {"name": "末次会议总结", "desc": "召开末次会议，总结审核结论", "legal_basis": "GSP第13条", "responsible": "质量负责人", "records": "内审总结报告"}]', '发布', '内审,质量体系,改进', 1, 16, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '综合管理');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (17, 'SOP流程', 'SOP-ZH-04', '管理评审流程', 'GSP第7条', '管理评审计划、输入准备、评审会议、输出决议和改进措施跟踪的全流程。', '<h3>流程说明</h3><p>管理评审是由企业最高管理者主持的质量管理体系评价活动，每年至少1次。</p><h3>评审输入</h3><ul><li>内审和外审结果</li><li>客户反馈和投诉</li><li>产品质量和不良事件情况</li><li>纠正和预防措施执行情况</li><li>法规变化影响</li><li>质量方针和目标达成情况</li></ul><h3>评审输出</h3><ul><li>质量管理体系改进决定</li><li>质量方针和目标修订</li><li>资源需求决定</li></ul>', '[{"name": "评审计划", "desc": "制定管理评审计划，确定时间、参加人员", "legal_basis": "GSP第7条", "responsible": "质量负责人", "records": "评审计划"}, {"name": "输入准备", "desc": "各部门准备评审输入资料", "legal_basis": "GSP第7条", "responsible": "各部门", "records": "评审输入文件"}, {"name": "评审会议", "desc": "最高管理者主持评审会议，评价体系适宜性", "legal_basis": "GSP第7条", "responsible": "企业负责人", "records": "评审会议记录"}, {"name": "输出决议", "desc": "形成评审决议和改进措施", "legal_basis": "GSP第7条", "responsible": "质量负责人", "records": "评审报告"}, {"name": "措施跟踪", "desc": "跟踪改进措施落实情况", "legal_basis": "GSP第7条", "responsible": "质管员", "records": "措施跟踪记录"}]', '发布', '管理评审,质量方针,持续改进', 0, 17, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '综合管理');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (18, 'SOP流程', 'SOP-ZH-05', '文件控制管理流程', 'GSP第7条', '质量管理体系文件的起草、审核、批准、发布、修订、回收和作废的全生命周期管理。', '<h3>流程说明</h3><p>文件控制是质量管理体系的基石，确保各岗位使用的是最新有效的文件版本。</p><h3>文件分类</h3><ul><li>一级文件：质量手册</li><li>二级文件：程序文件</li><li>三级文件：作业指导书（SOP）</li><li>四级文件：记录表单</li></ul><h3>控制要求</h3><ul><li>文件须经起草→审核→批准→发布流程</li><li>文件变更须进行版本控制，保留变更记录</li><li>作废文件须及时回收并标识"作废"</li><li>文件保存期限：不少于5年</li></ul>', '[{"name": "文件起草", "desc": "起草人编写文件内容", "legal_basis": "GSP第7条", "responsible": "文件起草人", "records": "文件草案"}, {"name": "文件审核", "desc": "质量负责人审核文件内容的合规性和适用性", "legal_basis": "GSP第7条", "responsible": "质量负责人", "records": "审核意见"}, {"name": "文件批准", "desc": "企业负责人批准文件发布", "legal_basis": "GSP第7条", "responsible": "企业负责人", "records": "批准记录"}, {"name": "文件发布", "desc": "编号、登记、分发文件到各使用部门", "legal_basis": "GSP第7条", "responsible": "质管员", "records": "文件分发记录"}, {"name": "文件修订", "desc": "文件修订时更新版本号，回收旧版本", "legal_basis": "GSP第7条", "responsible": "质管员", "records": "修订记录"}, {"name": "作废回收", "desc": "作废文件回收并标识\\"作废\\"章", "legal_basis": "GSP第7条", "responsible": "质管员", "records": "作废回收记录"}]', '发布', '文件,控制,版本', 0, 18, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '综合管理');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (19, 'SOP流程', 'SOP-ZH-06', '记录管理流程', 'GSP第7条', '质量记录的填写、收集、归档、保存和销毁的全生命周期管理。', '<h3>流程说明</h3><p>质量记录是证明质量管理体系有效运行的客观证据，须规范填写和妥善保存。</p><h3>记录控制要求</h3><ul><li>记录须及时、真实、完整填写</li><li>不得随意涂改，修改须签名并保持原字迹可辨</li><li>记录保存期限：不少于5年（特殊产品按法规要求）</li><li>记录销毁须经审批并记录</li></ul>', '[{"name": "记录填写", "desc": "操作人员及时、真实、完整填写记录", "legal_basis": "GSP第7条", "responsible": "操作人员", "records": "质量记录"}, {"name": "记录收集", "desc": "定期收集各部门质量记录", "legal_basis": "GSP第7条", "responsible": "质管员", "records": "记录移交单"}, {"name": "记录归档", "desc": "按类别、时间归档保存", "legal_basis": "GSP第7条", "responsible": "质管员", "records": "归档目录"}, {"name": "记录查阅", "desc": "提供记录查阅服务，登记查阅记录", "legal_basis": "GSP第7条", "responsible": "质管员", "records": "查阅登记表"}, {"name": "记录销毁", "desc": "超过保存期限的记录经审批后销毁", "legal_basis": "GSP第7条", "responsible": "质量负责人", "records": "销毁记录"}]', '发布', '记录,归档,保存', 0, 19, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '综合管理');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (20, 'SOP流程', 'SOP-ZH-07', '顾客满意度调查流程', 'GSP第73-76条', '顾客满意度调查计划、实施、分析、改进和回访的全流程管理。', '<h3>流程说明</h3><p>顾客满意度调查是了解客户需求和改进服务质量的重要手段，每年至少进行1次。</p><h3>调查维度</h3><ul><li>产品质量满意度</li><li>交货及时性</li><li>服务态度</li><li>售后支持</li><li>价格合理性</li></ul>', '[{"name": "调查计划", "desc": "制定年度顾客满意度调查计划", "legal_basis": "GSP第73条", "responsible": "销售助理", "records": "调查计划"}, {"name": "问卷设计", "desc": "设计满意度调查问卷", "legal_basis": "GSP第73条", "responsible": "质管员", "records": "调查问卷"}, {"name": "调查实施", "desc": "通过线上/线下/电话等方式实施调查", "legal_basis": "GSP第75条", "responsible": "销售助理", "records": "调查记录"}, {"name": "数据分析", "desc": "统计分析调查结果，形成报告", "legal_basis": "GSP第75条", "responsible": "质管员", "records": "满意度分析报告"}, {"name": "改进措施", "desc": "针对不满意项制定改进措施", "legal_basis": "GSP第76条", "responsible": "质量负责人", "records": "改进措施计划"}, {"name": "回访验证", "desc": "回访客户验证改进效果", "legal_basis": "GSP第76条", "responsible": "销售助理", "records": "回访记录"}]', '发布', '满意度,调查,改进', 0, 20, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '综合管理');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (21, '管理制度', 'ZD-01', '质量管理制度总则', 'GSP第7条', '阐述质量管理制度的总体要求、适用范围、质量方针和目标。', '<h3>总则</h3><p>本制度是卓盟医疗器械经营质量管理的纲领性文件，适用于公司医疗器械经营全过程。</p><h3>质量方针</h3><p>合法经营、质量第一、规范管理、持续改进。</p><h3>质量目标</h3><ul><li>产品合格率：100%</li><li>客户投诉处理率：100%</li><li>不良事件上报率：100%</li><li>培训考核合格率：≥95%</li><li>资质档案完整率：100%</li></ul><h3>适用范围</h3><p>适用于公司所有与医疗器械采购、验收、储存、销售、运输、售后服务相关的部门和人员。</p>', '[]', '发布', '制度,质量,总则', 1, 1, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '质量体系');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (22, '管理制度', 'ZD-02', '质量责任制', 'GSP第14-17条', '明确各岗位的质量职责和责任，建立层层落实的质量责任体系。', '<h3>质量责任体系</h3><p>建立从企业负责人到一线员工的质量责任制，明确各岗位质量职责。</p><h3>岗位职责</h3><ul><li><b>企业负责人</b>：对质量管理全面负责，提供资源保障</li><li><b>质量负责人</b>：负责质量管理体系建设和运行</li><li><b>质管员</b>：负责日常质量监督、审核和记录</li><li><b>采购员</b>：负责供应商选择和采购合规</li><li><b>验收员</b>：负责到货验收和质量检查</li><li><b>库管员</b>：负责仓储管理和养护检查</li><li><b>销售助理</b>：负责客户资质审核和销售记录</li></ul>', '[]', '发布', '责任,质量,岗位', 1, 2, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '质量体系');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (23, '管理制度', 'ZD-03', '质量否决权制度', 'GSP第7条', '质量负责人对不合格品、不合格供应商、不合格客户行使质量否决权的制度。', '<h3>质量否决权</h3><p>质量负责人对以下事项行使质量否决权：</p><ul><li>不合格品的入库和出库</li><li>不合格供应商的采购</li><li>不合格客户的销售</li><li>不合格运输条件的配送</li><li>不合格设施设备的使用</li></ul><h3>行使方式</h3><p>质量负责人以书面形式行使否决权，被否决部门须立即停止相关活动并整改。对否决有异议的，可向企业负责人申诉，但在申诉期间否决决定不停止执行。</p>', '[]', '发布', '质量否决,权限制约', 0, 3, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '质量体系');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (24, '管理制度', 'ZD-04', '不合格品管理制度', 'GSP第57条', '不合格品的标识、隔离、调查、处置和记录管理制度。', '<h3>制度说明</h3><p>不合格品管理是防止不合格品流入市场的关键控制点。</p><h3>不合格品标识</h3><ul><li>红色标识：不合格品</li><li>黄色标识：待验品</li><li>绿色标识：合格品</li></ul><h3>处置方式</h3><ul><li>退货：退回供应商</li><li>换货：要求供应商换货</li><li>销毁：无法退货/换货的进行销毁</li><li>报损：登记报损并销账</li></ul>', '[]', '发布', '不合格品,制度,处置', 0, 4, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '质量体系');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (25, '管理制度', 'ZD-05', '纠正与预防措施(CAPA)管理制度', 'GSP第12-13条', '纠正措施和预防措施的发起、调查、实施、验证和关闭的管理制度。', '<h3>CAPA管理制度</h3><p>纠正与预防措施（CAPA）是质量管理体系持续改进的核心机制。</p><h3>纠正措施</h3><p>针对已发生的不符合项，消除根本原因防止再发生。</p><h3>预防措施</h3><p>针对潜在的不符合项，消除原因防止发生。</p><h3>CAPA流程</h3><ul><li>问题识别 → 原因调查 → 措施制定 → 措施实施 → 效果验证 → 关闭归档</li></ul>', '[{"name": "问题识别", "desc": "识别不符合项或潜在风险", "legal_basis": "GSP第12条", "responsible": "质管员", "records": "CAPA发起单"}, {"name": "原因调查", "desc": "调查问题根本原因", "legal_basis": "GSP第12条", "responsible": "质管员", "records": "原因分析报告"}, {"name": "措施制定", "desc": "制定纠正和预防措施", "legal_basis": "GSP第12条", "responsible": "质量负责人", "records": "CAPA计划"}, {"name": "措施实施", "desc": "按计划实施纠正和预防措施", "legal_basis": "GSP第12条", "responsible": "责任部门", "records": "实施记录"}, {"name": "效果验证", "desc": "验证措施实施效果", "legal_basis": "GSP第13条", "responsible": "质管员", "records": "验证报告"}, {"name": "关闭归档", "desc": "确认有效后关闭CAPA并归档", "legal_basis": "GSP第13条", "responsible": "质量负责人", "records": "关闭报告"}]', '发布', 'CAPA,纠正,预防', 0, 5, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '质量体系');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (26, '法规制度', 'LAW-01', '医疗器械监督管理条例', '国务院令第739号', '医疗器械监督管理的最高行政法规，确立注册备案、分类管理、经营许可等基本制度。', '<h3>法规概述</h3><p>《医疗器械监督管理条例》（国务院令第739号）于2021年6月1日起施行，是医疗器械监督管理的最高行政法规。</p><h3>核心制度</h3><ul><li>分类管理制度（一类/二类/三类）</li><li>注册与备案制度</li><li>生产/经营许可与备案制度</li><li>使用质量管理制度</li><li>不良事件监测制度</li><li>召回制度</li></ul><h3>法律责任</h3><p>违反条例规定将面临警告、罚款、没收违法所得、吊销许可证等行政处罚，严重者追究刑事责任。</p>', '[]', '发布', '法规,条例,监督', 0, 1, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '法律法规');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (27, '法规制度', 'LAW-02', '医疗器械经营质量管理规范(GSP)', '国家药监局公告', '医疗器械经营环节采购、验收、储存、销售、运输、售后等全过程质量管理的核心规范。', '<h3>规范概述</h3><p>《医疗器械经营质量管理规范》（GSP）是医疗器械经营企业质量管理体系建设的核心依据。</p><h3>关键章节</h3><table border="1" style="border-collapse:collapse"><tr><th style="padding:6px">章节</th><th style="padding:6px">内容</th><th style="padding:6px">条款</th></tr><tr><td style="padding:6px">第一章</td><td style="padding:6px">总则</td><td style="padding:6px">第1-6条</td></tr><tr><td style="padding:6px">第二章</td><td style="padding:6px">质量管理体系</td><td style="padding:6px">第7-13条</td></tr><tr><td style="padding:6px">第三章</td><td style="padding:6px">人员与培训</td><td style="padding:6px">第14-20条</td></tr><tr><td style="padding:6px">第四章</td><td style="padding:6px">设施设备</td><td style="padding:6px">第21-27条</td></tr><tr><td style="padding:6px">第五章</td><td style="padding:6px">采购</td><td style="padding:6px">第28-38条</td></tr><tr><td style="padding:6px">第六章</td><td style="padding:6px">收货与验收</td><td style="padding:6px">第39-45条</td></tr><tr><td style="padding:6px">第七章</td><td style="padding:6px">入库与储存</td><td style="padding:6px">第46-53条</td></tr><tr><td style="padding:6px">第八章</td><td style="padding:6px">养护</td><td style="padding:6px">第54-58条</td></tr><tr><td style="padding:6px">第九章</td><td style="padding:6px">销售</td><td style="padding:6px">第59-67条</td></tr><tr><td style="padding:6px">第十章</td><td style="padding:6px">出库与运输</td><td style="padding:6px">第68-72条</td></tr><tr><td style="padding:6px">第十一章</td><td style="padding:6px">售后服务</td><td style="padding:6px">第73-76条</td></tr></table>', '[]', '发布', 'GSP,经营,规范', 0, 2, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '规范标准');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (28, '法规制度', 'LAW-03', '医疗器械经营许可管理办法', '国家市场监督管理总局令', '医疗器械经营许可和备案管理的部门规章，规定许可条件、申请程序和监督管理。', '<h3>规章概述</h3><p>《医疗器械经营许可管理办法》规定了医疗器械经营企业的许可和备案管理要求。</p><h3>许可与备案分类</h3><ul><li>第三类医疗器械经营：须取得《医疗器械经营许可证》</li><li>第二类医疗器械经营：须进行备案，取得《第二类医疗器械经营备案凭证》</li><li>第一类医疗器械经营：无需许可和备案</li></ul><h3>许可条件</h3><ul><li>具有与经营范围相适应的经营场所和库房</li><li>具有与经营范围相适应的质量管理人员</li><li>具有与经营产品相适应的设施设备</li><li>具有完善的质量管理制度</li></ul>', '[]', '发布', '许可,备案,经营', 0, 3, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '部门规章');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (29, '法规制度', 'LAW-04', '医疗器械不良事件监测管理办法', '国家药监局令', '医疗器械不良事件监测、报告、调查和评价的管理办法。', '<h3>办法概述</h3><p>《医疗器械不良事件监测管理办法》规定了医疗器械不良事件的监测、报告和调查要求。</p><h3>报告义务</h3><ul><li>医疗器械经营企业是不良事件报告的法定义务人</li><li>须建立不良事件监测制度</li><li>须配备专职或兼职监测人员</li><li>须按规定时限上报</li></ul><h3>上报时限</h3><ul><li>导致死亡：5个工作日内</li><li>导致严重伤害：15个工作日内</li><li>一般不良事件：30个工作日内</li></ul>', '[]', '发布', '不良事件,监测,办法', 0, 4, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '部门规章');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (30, '法规制度', 'LAW-05', '医疗器械召回管理办法', '国家药监局令', '医疗器械召回的级别、程序、时限和监督管理的办法。', '<h3>办法概述</h3><p>《医疗器械召回管理办法》规定了医疗器械缺陷的召回程序和要求。</p><h3>召回级别</h3><table border="1" style="border-collapse:collapse"><tr><th style="padding:6px">级别</th><th style="padding:6px">健康损害程度</th><th style="padding:6px">通知时限</th></tr><tr><td style="padding:6px">一级召回</td><td style="padding:6px">严重健康损害或死亡</td><td style="padding:6px">24小时内</td></tr><tr><td style="padding:6px">二级召回</td><td style="padding:6px">暂时性或可逆健康损害</td><td style="padding:6px">48小时内</td></tr><tr><td style="padding:6px">三级召回</td><td style="padding:6px">健康损害可能性较小</td><td style="padding:6px">72小时内</td></tr></table><h3>召回方式</h3><ul><li>主动召回：企业自行发现缺陷主动召回</li><li>责令召回：监管部门责令召回</li></ul>', '[]', '发布', '召回,办法,风险', 0, 5, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '部门规章');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (31, '培训资料', 'TRN-01', '医疗器械分类规则与目录解读', 'GSP第3条', '解读医疗器械分类规则（一类/二类/三类）和分类目录，帮助员工正确判断产品类别。', '<h3>培训目标</h3><p>掌握医疗器械分类的基本原则和判定方法，能正确查阅分类目录。</p><h3>培训内容</h3><ul><li>医疗器械定义和范围</li><li>分类原则：风险程度（低/中/高）</li><li>一类：常规管理足以保证安全性（如外科用手术器械）</li><li>二类：需要严格控制以保证安全性有效性（如医用电子仪器）</li><li>三类：植入人体或用于维持生命需要特别控制（如植入式心脏起搏器）</li><li>分类目录查阅方法</li></ul><h3>考核方式</h3><p>笔试（80分及格）+ 实操（查阅分类目录）</p>', '[]', '发布', '培训,分类,目录', 3, 1, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '入职培训');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (32, '培训资料', 'TRN-02', 'GSP规范要点解读培训', 'GSP全文', 'GSP规范的核心条款解读，帮助员工理解合规要求并在日常工作中落实。', '<h3>培训目标</h3><p>理解GSP规范的核心要求，掌握各业务环节的合规要点。</p><h3>培训大纲</h3><ul><li>GSP概述与质量管理体系要求</li><li>人员与培训要求（第14-20条）</li><li>设施设备要求（第21-27条）</li><li>采购管理要求（第28-38条）</li><li>收货验收要求（第39-45条）</li><li>入库储存要求（第46-53条）</li><li>养护管理要求（第54-58条）</li><li>销售出库要求（第59-67条）</li><li>售后服务要求（第73-76条）</li></ul><h3>考核方式</h3><p>笔试（80分及格）</p>', '[]', '发布', 'GSP,培训,规范', 1, 2, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '岗位培训');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (33, '培训资料', 'TRN-03', '不良事件监测与报告培训', '不良事件监测办法', '不良事件的识别、评估、上报流程和注意事项的专项培训。', '<h3>培训目标</h3><p>掌握不良事件的识别方法，熟悉上报流程和时限要求。</p><h3>培训内容</h3><ul><li>不良事件定义和分类</li><li>不良事件识别要点</li><li>严重程度评估方法</li><li>上报流程和时限</li><li>调查分析方法</li><li>纠正预防措施</li></ul><h3>案例分析</h3><p>通过实际案例分析，加深对不良事件监测的理解。</p><h3>考核方式</h3><p>笔试（80分及格）+ 案例分析</p>', '[]', '发布', '不良事件,培训,报告', 0, 3, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '岗位培训');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (34, '培训资料', 'TRN-04', '医疗器械法规体系概述', '全法规', '医疗器械法规体系的整体架构和主要法规解读，帮助员工建立法规合规意识。', '<h3>培训目标</h3><p>了解医疗器械法规体系架构，建立法规合规意识。</p><h3>法规体系</h3><table border="1" style="border-collapse:collapse"><tr><th style="padding:6px">层级</th><th style="padding:6px">法规名称</th><th style="padding:6px">主要内容</th></tr><tr><td style="padding:6px">法律</td><td style="padding:6px">药品管理法</td><td style="padding:6px">医疗器械管理基本法律</td></tr><tr><td style="padding:6px">行政法规</td><td style="padding:6px">医疗器械监督管理条例</td><td style="padding:6px">注册备案、分类管理、经营许可等</td></tr><tr><td style="padding:6px">部门规章</td><td style="padding:6px">经营许可办法/召回办法/不良事件办法</td><td style="padding:6px">具体管理制度</td></tr><tr><td style="padding:6px">规范文件</td><td style="padding:6px">GSP规范/分类规则</td><td style="padding:6px">技术要求和操作规范</td></tr></table><h3>考核方式</h3><p>笔试（80分及格）</p>', '[]', '发布', '法规,培训,体系', 0, 4, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '法规培训');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (35, '质量文件', 'QA-01', '质量管理体系文件架构', 'GSP第7条', '描述质量管理体系四级文件架构：质量手册、程序文件、作业指导书、记录表单。', '<h3>文件架构</h3><table border="1" style="border-collapse:collapse"><tr><th style="padding:6px">级别</th><th style="padding:6px">文件类型</th><th style="padding:6px">内容</th></tr><tr><td style="padding:6px">一级</td><td style="padding:6px">质量手册</td><td style="padding:6px">质量方针、目标、组织架构、职责</td></tr><tr><td style="padding:6px">二级</td><td style="padding:6px">程序文件</td><td style="padding:6px">各业务流程的程序规定</td></tr><tr><td style="padding:6px">三级</td><td style="padding:6px">作业指导书</td><td style="padding:6px">具体操作的SOP</td></tr><tr><td style="padding:6px">四级</td><td style="padding:6px">记录表单</td><td style="padding:6px">操作记录和质量记录</td></tr></table><h3>文件控制要求</h3><ul><li>所有文件须经审批后发布</li><li>文件变更须进行版本控制</li><li>作废文件须及时回收并标识</li><li>记录保存期限不少于5年</li></ul>', '[]', '发布', '质量体系,文件,架构', 0, 1, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '质量手册');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (36, '质量文件', 'QA-02', '质量方针与目标管理程序', 'GSP第7条', '质量方针的制定、传达、评审和修订程序，以及质量目标的制定、分解和考核。', '<h3>质量方针</h3><p>合法经营、质量第一、规范管理、持续改进。</p><h3>质量目标</h3><table border="1" style="border-collapse:collapse"><tr><th style="padding:6px">目标</th><th style="padding:6px">指标</th><th style="padding:6px">考核频次</th></tr><tr><td style="padding:6px">产品合格率</td><td style="padding:6px">100%</td><td style="padding:6px">月度</td></tr><tr><td style="padding:6px">客户投诉处理率</td><td style="padding:6px">100%</td><td style="padding:6px">月度</td></tr><tr><td style="padding:6px">不良事件上报率</td><td style="padding:6px">100%</td><td style="padding:6px">季度</td></tr><tr><td style="padding:6px">培训合格率</td><td style="padding:6px">≥95%</td><td style="padding:6px">年度</td></tr><tr><td style="padding:6px">资质档案完整率</td><td style="padding:6px">100%</td><td style="padding:6px">季度</td></tr></table><h3>管理程序</h3><ul><li>质量方针由企业负责人制定，每年管理评审时评估其适宜性</li><li>质量目标由质量负责人分解到各部门，每季度考核</li><li>未达成目标时须分析原因并制定改进措施</li></ul>', '[]', '发布', '质量方针,目标,程序', 0, 2, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '程序文件');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (37, '质量文件', 'QA-03', '文件控制程序', 'GSP第7条', '质量管理体系文件的起草、审核、批准、发布、修订、回收和作废的控制程序。', '<h3>文件控制程序</h3><p>本程序规定了质量管理体系文件的全生命周期管理要求。</p><h3>文件分类</h3><ul><li>内部文件：质量手册、程序文件、SOP、记录表单</li><li>外部文件：法规、标准、供应商提供的技术文件</li></ul><h3>文件编号规则</h3><ul><li>质量手册：QM-001</li><li>程序文件：QP-XX</li><li>作业指导书：WI-XX</li><li>记录表单：FM-XX</li></ul><h3>版本控制</h3><p>文件版本号格式：A/0（A为版本号，0为修订次数），修订时修订次数递增，大改时版本号递增。</p>', '[]', '发布', '文件,控制,程序', 0, 3, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '程序文件');
INSERT INTO `knowledge_base` (`id`, `category`, `code`, `title`, `gsp_ref`, `summary`, `content`, `steps`, `status`, `tags`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`, `subcategory`) VALUES (38, '质量文件', 'QA-04', '记录控制程序', 'GSP第7条', '质量记录的标识、收集、归档、查阅、保存和销毁的控制程序。', '<h3>记录控制程序</h3><p>本程序规定了质量记录的全生命周期管理要求。</p><h3>记录要求</h3><ul><li>记录须及时填写，不得追记</li><li>记录须真实、完整、清晰</li><li>修改须签名并保持原字迹可辨</li><li>记录不得随意复印和外借</li></ul><h3>保存期限</h3><table border="1" style="border-collapse:collapse"><tr><th style="padding:6px">记录类型</th><th style="padding:6px">保存期限</th></tr><tr><td style="padding:6px">采购验收记录</td><td style="padding:6px">不少于5年</td></tr><tr><td style="padding:6px">温湿度记录</td><td style="padding:6px">不少于5年</td></tr><tr><td style="padding:6px">养护记录</td><td style="padding:6px">不少于5年</td></tr><tr><td style="padding:6px">销售出库记录</td><td style="padding:6px">不少于5年</td></tr><tr><td style="padding:6px">不良事件记录</td><td style="padding:6px">不少于5年</td></tr><tr><td style="padding:6px">培训记录</td><td style="padding:6px">员工在职期间+离职后2年</td></tr><tr><td style="padding:6px">健康档案</td><td style="padding:6px">员工在职期间+离职后2年</td></tr></table>', '[]', '发布', '记录,控制,程序', 0, 4, '系统', '2026-08-08 18:30', '2026-08-08 18:30', '程序文件');
